package main

import "fmt"

type lock struct {
	tx   int
	mode string
}

func main() {
	held := []lock{}
	requests := []lock{{1, "S"}, {2, "S"}, {3, "X"}, {1, "X"}}
	for _, r := range requests {
		ok := true
		for _, h := range held {
			if h.tx != r.tx && (h.mode == "X" || r.mode == "X") {
				ok = false
			}
		}
		if ok {
			held = append(held, r)
			fmt.Printf("T%d %s granted\n", r.tx, r.mode)
		} else {
			fmt.Printf("T%d %s waits\n", r.tx, r.mode)
		}
	}
}

function levels(fanout, keys) {
  let height = 1, capacity = fanout;
  while (capacity < keys) {
    capacity *= fanout;
    height++;
  }
  return height;
}
console.log(levels(500, 1_000_000), levels(100, 1_000_000), levels(2, 1_000_000));

