const frames = [];   // { page, ref }
let hand = 0;
const evicted = [];
for (const page of [1, 2, 3, 1, 4, 5]) {
  const hit = frames.find(f => f.page === page);
  if (hit) { hit.ref = 1; continue; }
  if (frames.length < 3) { frames.push({ page, ref: 1 }); continue; }
  while (frames[hand].ref === 1) {   // give a second chance
    frames[hand].ref = 0;
    hand = (hand + 1) % 3;
  }
  evicted.push(frames[hand].page);
  frames[hand] = { page, ref: 1 };
  hand = (hand + 1) % 3;
}
console.log("evicted:", evicted.join(","));
console.log("frames:", frames.map(f => f.page).join(","));

function commit(votes) {
  // phase 1: prepare
  const allYes = Object.values(votes).every(v => v === "yes");
  const decision = allYes ? "COMMIT" : "ABORT";
  // phase 2: tell every participant the same decision
  return decision + " -> " + Object.keys(votes).map(p => `${p}:${decision.toLowerCase()}`).join(" ");
}
console.log(commit({ orders: "yes", stock: "yes", billing: "yes" }));
console.log(commit({ orders: "yes", stock: "no", billing: "yes" }));

package main

import "fmt"

type version struct {
	val        string
	xmin, xmax int // xmax 0 = not deleted
}

// snapshot: xids < 100 are finished unless listed in active; xids >= 100 are in the future.
var active = map[int]bool{95: true}

func committedForMe(x int) bool { return x < 100 && !active[x] }

func main() {
	rows := []version{{"a", 90, 0}, {"b", 95, 0}, {"c", 80, 92}, {"d", 85, 95}, {"e", 101, 0}}
	for _, r := range rows {
		visible := committedForMe(r.xmin) && (r.xmax == 0 || !committedForMe(r.xmax))
		fmt.Print(r.val, "=", visible, " ")
	}
	fmt.Println()
}

package main

import "fmt"

func main() {
	// waitsFor[t] = transaction that t is waiting on (0 = not waiting)
	waitsFor := map[int]int{1: 2, 2: 3, 3: 1, 4: 1, 5: 0}
	for _, start := range []int{4, 5} {
		seen := map[int]bool{}
		t := start
		for t != 0 && !seen[t] {
			seen[t] = true
			t = waitsFor[t]
		}
		if t == 0 {
			fmt.Printf("T%d: no deadlock\n", start)
		} else {
			fmt.Printf("T%d: reaches cycle at T%d\n", start, t)
		}
	}
}
